import assert from "node:assert/strict";
import { test } from "node:test";
import { qrMatrix, qrSvg, code128Symbols, code128Svg } from "../v2-labels.js";
import { imageDataUrl } from "../v2-client.js";
import { createHash } from "node:crypto";

test("QR byte matrices match independently run upstream reference fixtures", () => {
  // Generated by test/e2e/qr-reference-check.mjs, ECI 26 / byte / L / mask 0.
  const fixtures = [
    ["BC-000001", "c1b6f1793be88887b42594faebda7cd8577a8f90c276d443135f69c32c9bb04c"],
    ["A-B-C-04", "15bb14062015cfe7cbf2c88a1be17d1f9fb5afcdfb3503fb999ff509a2cb5707"],
    ["SN-000001", "6d48c984d59cbf1a51418d48e21441959e8298977bc9a81e5c456e347b10bc02"],
    ["仓储商品-123", "4fc1ec9c8c2b50bd74d6874ec32dfd54debfb91851b6ff5a6349e612b77093ce"],
    ["X".repeat(128), "2e02152af59a919f3096d8e7624be13a7e000f395bcd26d3f758ac705d27df40"],
    ["仓".repeat(128), "ddf2b5da02f90869a5c2c2caf682e684b7ebe33707cd2220ebd567a25f37ea6a"]
  ];
  for (const [text, hash] of fixtures) {
    const actual = createHash("sha256").update(qrMatrix(text, 0).map(row => row.map(Number).join("")).join("\n")).digest("hex");
    assert.equal(actual, hash);
  }
});

test("QR has square modules, three finder patterns and preserves quiet zone in SVG", () => {
  const matrix = qrMatrix("BC-000001"); assert.equal(matrix.length, 21); assert.ok(matrix.every(row => row.length === 21));
  for (const [x, y] of [[3, 3], [17, 3], [3, 17]]) assert.equal(matrix[y][x], true);
  const svg = qrSvg("BC-000001"); assert.match(svg, /viewBox="0 0 29 29"/); assert.match(svg, /shape-rendering="crispEdges"/);
});
test("QR supports Unicode and long identifiers without silently changing their value", () => {
  assert.ok(qrMatrix("仓".repeat(128)).length > 21); assert.ok(qrMatrix("X".repeat(128)).length > 21);
  for (const value of ["", "x".repeat(129), "a\nb", "a\0b"]) assert.throws(() => qrMatrix(value));
  assert.throws(() => qrMatrix("a", 8));
});
test("code128 B checksum and symbol encoding match the expected identifier", () => {
  assert.deepEqual(code128Symbols("ABC"), [104, 33, 34, 35, 1, 106]);
  assert.notDeepEqual(code128Symbols("ABC"), code128Symbols("abc"));
  assert.match(code128Svg("BC-000001"), /<path/);
  assert.throws(() => code128Symbols("中文")); assert.throws(() => code128Symbols("a\nb"));
});
test("label SVG never injects untrusted text into markup", () => {
  const text = '<img src=x onerror="alert(1)">';
  for (const svg of [qrSvg(text), code128Svg(text)]) { assert.ok(!svg.includes("<img")); assert.ok(svg.includes("&lt;img")); }
});
test("image previews allow only size-bounded PNG/JPEG data and no SVG or external URL", () => {
  assert.equal(imageDataUrl("YWJj", "image/png"), "data:image/png;base64,YWJj");
  assert.equal(imageDataUrl(null, null), null);
  assert.throws(() => imageDataUrl("YWJj", "image/svg+xml")); assert.throws(() => imageDataUrl("https://evil.example", "image/png"));
  assert.throws(() => imageDataUrl("x".repeat(2796205), "image/png"));
});
